1	// Static file server for local development: node server.mjs  (PORT defaults to 4173)
2	import http from 'node:http';
3	import fs from 'node:fs';
4	import path from 'node:path';
5	
6	const root = path.join(path.dirname(new URL(import.meta.url).pathname), 'public');
7	const port = Number(process.env.PORT || 4173);
8	const types = { '.html': 'text/html; charset=utf-8', '.css': 'text/css', '.js': 'text/javascript', '.svg': 'image/svg+xml' };
9	
10	http.createServer((req, res) => {
11	  const url = new URL(req.url, 'http://localhost');
12	  let file = path.normalize(path.join(root, url.pathname === '/' ? 'index.html' : url.pathname));
13	  if (!file.startsWith(root) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) {
14	    res.writeHead(404, { 'Content-Type': 'text/plain' });
15	    return res.end('Not found\n');
16	  }
17	  res.writeHead(200, { 'Content-Type': types[path.extname(file)] || 'application/octet-stream' });
18	  fs.createReadStream(file).pipe(res);
19	}).listen(port, '127.0.0.1', () => console.log(`http://127.0.0.1:${port}/`));
