1	// Pure cart logic, shared by the page (app.js) and the unit tests. Prices are integer cents.
2	
3	export const MAX_QTY = 10;
4	export const MIN_QTY = 1;
5	export const PROMOS = { SAVE10: 0.10 };
6	
7	export const DEFAULT_ITEMS = [
8	  { sku: 'KB-200', name: 'Ergonomic keyboard', price: 12900, qty: 1 },
9	  { sku: 'MN-27', name: '27-inch monitor', price: 89900, qty: 1 },
10	  { sku: 'CB-C2', name: 'USB-C cable (2 m)', price: 1250, qty: 2 },
11	];
12	
13	export function formatMoney(cents) {
14	  return '$' + (cents / 100).toFixed(2);
15	}
16	
17	export function lineTotal(item) {
18	  return item.price * item.qty;
19	}
20	
21	export function subtotal(items) {
22	  return items.reduce((s, it) => s + lineTotal(it), 0);
23	}
24	
25	export function increment(item) {
26	  if (item.qty <= MAX_QTY) item.qty += 1;
27	  return item;
28	}
29	
30	export function decrement(item) {
31	  if (item.qty >= MIN_QTY) item.qty -= 1;
32	  return item;
33	}
34	
35	// Returns the promo rate for a code, or null if the code is unknown. Codes are case-insensitive.
36	export function promoRate(code) {
37	  const rate = PROMOS[String(code).trim().toUpperCase()];
38	  return rate === undefined ? null : rate;
39	}
40	
41	export function discountFor(items, rate) {
42	  return Math.round(subtotal(items) * rate);
43	}
