1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { DEFAULT_ITEMS, subtotal, lineTotal, increment, decrement, promoRate, discountFor, formatMoney } from '../public/cart.js';
4	
5	const fresh = () => structuredClone(DEFAULT_ITEMS);
6	
7	test('subtotal of the default cart', () => {
8	  assert.equal(subtotal(fresh()), 12900 + 89900 + 2 * 1250);
9	});
10	
11	test('increment and decrement change the quantity', () => {
12	  const item = { price: 500, qty: 2 };
13	  increment(item);
14	  assert.equal(item.qty, 3);
15	  decrement(item);
16	  decrement(item);
17	  assert.equal(item.qty, 1);
18	  assert.equal(lineTotal(item), 500);
19	});
20	
21	test('SAVE10 gives 10 percent off, any case', () => {
22	  assert.equal(promoRate('SAVE10'), 0.10);
23	  assert.equal(promoRate(' save10 '), 0.10);
24	  assert.equal(promoRate('FREESHIP'), null);
25	  assert.equal(discountFor(fresh(), 0.10), 10530);
26	});
27	
28	test('formatMoney shows dollars and cents', () => {
29	  assert.equal(formatMoney(1250), '$12.50');
30	  assert.equal(formatMoney(5), '$0.05');
31	});
